import java.util.*;

public class Main {
    public static void main(String[] args) {

        List<Integer> numbers = new ArrayList<>(
            Arrays.asList(3, 17, 8, 42, 5, 99, 14, 66, 7, 31));

        System.out.println("Original: " + numbers);

        // Remove all numbers > 20 using Iterator
        Iterator<Integer> it = numbers.iterator();
        while (it.hasNext()) {
            if (it.next() > 20) it.remove();
        }
        System.out.println("<= 20 only: " + numbers);

        // Double each remaining number using ListIterator
        ListIterator<Integer> lit = numbers.listIterator();
        while (lit.hasNext()) {
            lit.set(lit.next() * 2);
        }
        System.out.println("Doubled: " + numbers);

        // Traverse backwards
        System.out.print("Reversed: ");
        while (lit.hasPrevious()) {
            System.out.print(lit.previous() + " ");
        }
    }
}

